const countryData=[{name:"Brasil",code:"BR",dialCode:"+55",flag:"🇧🇷",placeholder:"(11) 99999-9999",maskFormat:function(a){return a.length<=10?a.replace(/^(\d{2})(\d{4})(\d{0,4}).*/,"($1) $2-$3"):a.replace(/^(\d{2})(\d{5})(\d{0,4}).*/,"($1) $2-$3")}},{name:"Estados Unidos",code:"US",dialCode:"+1",flag:"🇺🇸",placeholder:"(555) 123-4567",maskFormat:function(a){return a.replace(/^(\d{3})(\d{3})(\d{0,4}).*/,"($1) $2-$3")}},{name:"Portugal",code:"PT",dialCode:"+351",flag:"🇵🇹",placeholder:"912 345 678",maskFormat:function(a){return a.replace(/^(\d{3})(\d{3})(\d{0,3}).*/,"$1 $2 $3")}},{name:"Itália",code:"IT",dialCode:"+39",flag:"🇮🇹",placeholder:"333 123 4567",maskFormat:function(a){return a.replace(/^(\d{3})(\d{3})(\d{0,4}).*/,"$1 $2 $3")}},{name:"Espanha",code:"ES",dialCode:"+34",flag:"🇪🇸",placeholder:"612 345 678",maskFormat:function(a){return a.replace(/^(\d{3})(\d{3})(\d{0,3}).*/,"$1 $2 $3")}}];